import{_ as e,c as s,o,a3 as t}from"./chunks/framework.Dk6sf0Ip.js";const i="/donandresdoc/assets/img1.C8imtRQ_.webp",r="/donandresdoc/assets/img2.BlyFtL-O.webp",l="/donandresdoc/assets/abrirajuste.BYcSO9wP.webp",n="/donandresdoc/assets/listaRegistros.itRT_qH7.webp",b=JSON.parse('{"title":"Flujo de Ajuste","description":"","frontmatter":{},"headers":[],"relativePath":"flows/ajustes/ajuste.md","filePath":"flows/ajustes/ajuste.md","lastUpdated":1759238350000}'),d={name:"flows/ajustes/ajuste.md"};function c(u,a,p,j,m,h){return o(),s("div",null,a[0]||(a[0]=[t('<h1 id="flujo-de-ajuste" tabindex="-1">Flujo de Ajuste <a class="header-anchor" href="#flujo-de-ajuste" aria-label="Permalink to &quot;Flujo de Ajuste&quot;">​</a></h1><p>Este flujo permite realizar ajustes de varios tipos, positivos y negativos en diferentes cuentas.</p><p>La estructura de los ajustes son idénticas, cambiando únicamente el impacto del ajuste (positivo o negativo).</p><h2 id="🔄-flujo-de-ajuste-general-positivo-o-negativo" tabindex="-1">🔄 Flujo de Ajuste General (Positivo o Negativo) <a class="header-anchor" href="#🔄-flujo-de-ajuste-general-positivo-o-negativo" aria-label="Permalink to &quot;🔄 Flujo de Ajuste General (Positivo o Negativo)&quot;">​</a></h2><p>La actividad o flujo lo encontraras en el - 1 ➡<code>Area de actividades</code> - y se mostrara en la tarjeta con nombre 2➡<code>AJUSTES</code></p><p><img src="'+i+'" alt="img1"></p><h3 id="inicio" tabindex="-1">Inicio <a class="header-anchor" href="#inicio" aria-label="Permalink to &quot;Inicio&quot;">​</a></h3><p>Descripción: Pantalla inicial para definir el tipo de ajuste a realizar si es positivo o negativo</p><p><img src="'+r+'" alt="img2"></p><ul><li><a href="#nuevo-ajuste">Crear Ajuste</a></li><li><a href="#abrir-los-ajustes">Abrir los ajustes</a></li></ul><h3 id="abrir-los-ajustes" tabindex="-1">Abrir los ajustes <a class="header-anchor" href="#abrir-los-ajustes" aria-label="Permalink to &quot;Abrir los ajustes&quot;">​</a></h3><p>Una vez realices click se desplegara hacia abajo los diferentes instancias del mismo ahi podrás hacer click en donde te muestra la cantidad de <code>rojos</code></p><p><img src="'+l+'" alt="abrir ajuste"></p><p>Al realizar el click se mostrara una tabla con todos los registros en la cual podrás seleccionar uno de ellos para abrirlo. Buscar en la parte superior</p><p><img src="'+n+'" alt="seleccionar registro"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Puede editar la vista de la tabla seleccionando las diferentes colomnas, puede hacer una vista momentanea, o bien guardarla para que quede de esa manera.</p></div><h3 id="nuevo-ajuste" tabindex="-1">Nuevo Ajuste <a class="header-anchor" href="#nuevo-ajuste" aria-label="Permalink to &quot;Nuevo Ajuste&quot;">​</a></h3><p>Una vez hagas click para crear un nuevo registro te dirigira a la actividad inicial.</p>',18)]))}const _=e(d,[["render",c]]);export{b as __pageData,_ as default};
